e">Hashtags / keywords<textarea name="hashtags"></textarea></label><label class="wide">Owner notes<textarea name="owner_notes"></textarea></label><label class="check"><input type="checkbox" name="approval_required" checked> Owner approval required</label></div><footer><button type="button" class="portal-button portal-button--secondary" data-close>Cancel</button><button class="portal-button portal-button--primary">Save work</button></footer></form></dialog>
